"""Ignore nodes and widgets by separate name or regex rules."""

from __future__ import annotations

import re


class WyslIgnoreRules:
    CATEGORY = "Wysl/工具"
    FUNCTION = "describe"
    RETURN_TYPES = ("STRING",)
    RETURN_NAMES = ("规则",)
    OUTPUT_NODE = True
    DESCRIPTION = "节点框忽略匹配的节点，选框框忽略匹配的选框。两个框都填写时，两边匹配到的内容都会被忽略。"

    @classmethod
    def INPUT_TYPES(cls):
        return {
            "required": {
                "名称": ("STRING", {"default": "忽略所有图像", "multiline": False}),
                "启用": ("BOOLEAN", {"default": False, "label_on": "启用", "label_off": "关闭"}),
                "节点": ("STRING", {
                    "default": "^图像",
                    "multiline": True,
                    "tooltip": "每行一条。匹配节点标题或类型名，匹配到的整个节点会被忽略。",
                }),
                "选框": ("STRING", {
                    "default": "",
                    "multiline": True,
                    "tooltip": "每行一条。匹配选框名称，匹配到的选框会被忽略。",
                }),
            }
        }

    @staticmethod
    def describe(名称, 启用, 节点, 选框):
        state = "启用" if 启用 else "关闭"
        return (f"{名称} [{state}]\n节点:\n{节点}\n选框:\n{选框}",)


def split_rules(text):
    return [line.strip() for line in str(text or "").splitlines() if line.strip()]


def rule_matches(rule, value):
    text = str(value or "")
    pattern = str(rule or "").strip()
    if not pattern or not text:
        return False
    if re.search(r"[\\^$.*+?()[\]{}|]", pattern):
        try:
            return re.search(pattern, text) is not None
        except re.error:
            return False
    return pattern in text


def any_rule_matches(rules, values):
    return any(rule_matches(rule, value) for rule in rules for value in values)


NODE_CLASS_MAPPINGS = {"WyslIgnoreRules": WyslIgnoreRules}
NODE_DISPLAY_NAME_MAPPINGS = {"WyslIgnoreRules": "Wysl-忽略规则"}
